import{c as l,Q as a,j as e,m as o}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"show_kernel_debug_data工具","description":"","frontmatter":{},"headers":[{"level":1,"title":"show\\\\_kernel\\\\_debug\\\\_data工具","slug":"show_kernel_debug_data工具"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"工具安装","slug":"工具安装"},{"level":2,"title":"使用方法","slug":"使用方法"},{"level":2,"title":"产物说明","slug":"产物说明"}],"relativePath":"guide/编程指南/附录/show_kernel_debug_data工具.md","filePath":"guide/编程指南/附录/show_kernel_debug_data工具.md"}'),s={name:"guide/编程指南/附录/show_kernel_debug_data工具.md"};function n(p,t,r,g,d,i){return a(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="show-kernel-debug-data工具" tabindex="-1">show_kernel_debug_data工具 <a class="header-anchor" href="#show-kernel-debug-data工具" aria-label="Permalink to &quot;show\\_kernel\\_debug\\_data工具&quot;">​</a></h1><p>在Ascend C算子程序代码中，用户可以使用AscendC::<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DumpTensor.md" target="_blank" rel="noreferrer">DumpTensor</a>、AscendC::<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/printf.md" target="_blank" rel="noreferrer">printf</a>、AscendC::<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/PrintTimeStamp.md" target="_blank" rel="noreferrer">PrintTimeStamp</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/ascendc_assert.md" target="_blank" rel="noreferrer">ascendc_assert</a>接口打印相关调试信息，并通过aclInit接口或直接配置acl.json文件，启用Dump配置，导出Ascend C算子Kernel的调测信息。本工具提供了对调测信息的离线解析能力，帮助用户获取并解析调试信息，即将导出的bin文件解析成可读格式。本工具的使用示例可参考<a href="https://gitcode.com/cann/asc-tools/tree/master/examples/01_show_kernel_debug_data" target="_blank" rel="noreferrer">show_kernel_debug_data样例</a>。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>show_kernel_debug_data支持多用户并发调用，但用户需要指定不同的落盘路径，否则可能出现落盘内容被覆盖等问题。</p></div><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;57.99999999999999%&quot;&gt;&lt;p&gt;&lt;span&gt;产品&lt;/span&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; align=&quot;center&quot; valign=&quot;top&quot; width=&quot;42%&quot;&gt;&lt;p&gt;是否支持&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;57.99999999999999%&quot;&gt;&lt;p&gt;&lt;span&gt;Ascend 950PR/Ascend 950DT&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; align=&quot;center&quot; valign=&quot;top&quot; width=&quot;42%&quot;&gt;&lt;p&gt;√&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;57.99999999999999%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas A3 训练系列产品&lt;/term&gt;/&lt;term&gt;Atlas A3 推理系列产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; align=&quot;center&quot; valign=&quot;top&quot; width=&quot;42%&quot;&gt;&lt;p&gt;√&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;57.99999999999999%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas A2 训练系列产品&lt;/term&gt;/&lt;term&gt;Atlas A2 推理系列产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; align=&quot;center&quot; valign=&quot;top&quot; width=&quot;42%&quot;&gt;&lt;p&gt;√&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;57.99999999999999%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas 200I/500 A2 推理产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; align=&quot;center&quot; valign=&quot;top&quot; width=&quot;42%&quot;&gt;&lt;p&gt;√&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;57.99999999999999%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas 推理系列产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; align=&quot;center&quot; valign=&quot;top&quot; width=&quot;42%&quot;&gt;&lt;p&gt;√&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;57.99999999999999%&quot;&gt;&lt;p&gt;&lt;span&gt;&lt;term&gt;Atlas 训练系列产品&lt;/term&gt;&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; align=&quot;center&quot; valign=&quot;top&quot; width=&quot;42%&quot;&gt;&lt;p&gt;x&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="工具安装" tabindex="-1">工具安装 <a class="header-anchor" href="#工具安装" aria-label="Permalink to &quot;工具安装&quot;">​</a></h2><ol><li><p>安装工具。</p><p>工具跟随CANN软件包发布（参考<a href="./../../入门教程/环境准备.html">环境准备</a>完成CANN安装），其路径默认为“\${INSTALL_DIR}/tools/show_kernel_debug_data”，其中\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。</p></li><li><p>设置环境变量。</p><ul><li><p>root用户安装Ascend-cann-toolkit包时</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source /usr/local/Ascend/cann/set_env.sh</span></span></code></pre></div></li><li><p>非root用户安装Ascend-cann-toolkit包时</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source \${HOME}/Ascend/cann/set_env.sh</span></span></code></pre></div></li></ul></li><li><p>检查工具是否安装成功。</p><p>执行如下命令，若能正常显示--help或-h信息，则表示工具环境正常，功能可正常使用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>show_kernel_debug_data -h</span></span></code></pre></div></li></ol><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><ul><li><p><strong>命令行方式</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>show_kernel_debug_data &lt;bin_file_path&gt; [&lt;output_path&gt;]</span></span></code></pre></div><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;19.39%&quot;&gt;&lt;p&gt;参数&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.110000000000003%&quot;&gt;&lt;p&gt;可选/必选&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;52.5%&quot;&gt;&lt;p&gt;说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;19.39%&quot;&gt;&lt;p&gt;&lt;bin_file_path&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.110000000000003%&quot;&gt;&lt;p&gt;必选&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;52.5%&quot;&gt;&lt;p&gt;kernel侧调试信息落盘的bin文件或包含bin文件的目录路径，例如“/input/dump_workspace.bin”。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;19.39%&quot;&gt;&lt;p&gt;&lt;output_path&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;28.110000000000003%&quot;&gt;&lt;p&gt;可选&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;52.5%&quot;&gt;&lt;p&gt;解析结果的保存路径，例如“/output_dir”。默认是当前命令行执行目录下。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p><strong>API方式</strong></p><p>获取kernel侧调试信息并解析成可读文件。函数原型如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def show_kernel_debug_data(bin_file_path: str, output_path: str = &#39;./&#39;) -&gt; None</span></span></code></pre></div><p>其中，输入参数说明如下。函数无输出参数和返回值。</p><ul><li>bin_file_path：kernel侧调试信息落盘的bin文件或包含bin文件的目录路径，字符串类型。</li><li>output_path：解析结果的保存路径，字符串类型，默认是当前接口调用脚本所在目录下。</li></ul><p>调用示例参考如下代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from show_kernel_debug_data import show_kernel_debug_data</span></span>
<span class="line"><span>show_kernel_debug_data(./input/dump_workspace.bin)</span></span></code></pre></div></li></ul><h2 id="产物说明" tabindex="-1">产物说明 <a class="header-anchor" href="#产物说明" aria-label="Permalink to &quot;产物说明&quot;">​</a></h2><p>工具解析结果文件目录结构如下。其中，dump_data目录是对DumpTensor、PrintTimeStamp接口解析的结果，index0对应DumpTensor接口中第二个参数desc=0时的打印，loop0表示切分后首个分块的数据打印。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>├ \${output_path}</span></span>
<span class="line"><span>├── PARSER_\${timestamp}                     // \${timestamp}表示时间戳</span></span>
<span class="line"><span>     ├── dump_data</span></span>
<span class="line"><span>     │   ├── 0                             // core0解析结果</span></span>
<span class="line"><span>     │   ├── core_0_index_0_loop_0.bin     // core0 desc0 progress0落盘信息</span></span>
<span class="line"><span>     │   ├── core_0_index_0_loop_0.txt     // core0 desc0 progress0解析结果</span></span>
<span class="line"><span>      ...</span></span>
<span class="line"><span>     │   ├── core_0_index_2_loop_15.bin    // core0 desc2 progress15落盘信息</span></span>
<span class="line"><span>     │   ├── core_0_index_2_loop_15.txt    // core0 desc2 progress15解析结果</span></span>
<span class="line"><span>     │   └── time_stamp_core_0.csv         // 时间戳信息</span></span>
<span class="line"><span>     │   ├── 1                             // core1解析结果</span></span>
<span class="line"><span>     │   ├── 2                             // core2解析结果</span></span>
<span class="line"><span>      ...         </span></span>
<span class="line"><span>     │   └── index_dtype.json              // index与数据类型的映射关系</span></span>
<span class="line"><span>     └── parser.log                         // 解析日志，包括printf、ascendc_assert接口的打印信息</span></span></code></pre></div>`,12)])])}const q=l(s,[["render",n]]);export{c as __pageData,q as default};
